		"Version": "v1.0.0",
		"Indirect": true,
		"Update": {
			"Version": "v1.1.0"
		}
	}`

	// Test 1: With -direct flag and -ci flag, should still exit with code 1 because there's an outdated direct module
	fmt.Println("Test 1: Running with -direct and -ci flags")
	var out1 bytes.Buffer
	exitCode1 := runWithExitCapture(func() {
		runner.Run(strings.NewReader(jsonInput), &out1, false, true, true, runner.StyleDefault)
	})
	fmt.Printf("Output:\n%s\n", out1.String())
	fmt.Printf("Exit code: %d\n\n", exitCode1)

	// Test 2: With -update flag and -ci flag, should still exit with code 1 because there are outdated modules
	fmt.Println("Test 2: Running with -update and -ci flags")
	var out2 bytes.Buffer
	exitCode2 := runWithExitCapture(func() {
		runner.Run(strings.NewReader(jsonInput), &out2, true, false, true, runner.StyleDefault)
	})
	fmt.Printf("Output:\n%s\n", out2.String())
	fmt.Printf("Exit code: %d\n\n", exitCode2)
}

func runWithExitCapture(f func()) int {
	// Save original OsExit
	originalOsExit := runner.OsExit

	// Channel to capture exit code
	exitCodeChan := make(chan int, 1)

	// Replace OsExit with our custom function
	runner.OsExit = func(code int) {
		exitCodeChan <- code
	}

	// Run the function
	f()

	// Restore original OsExit
	runner.OsExit = originalOsExit

	// Return the captured exit code, or 0 if none was captured
	select {
	case code := <-exitCodeChan:
		return code
	default:
		return 0
	}
}
